mapper.select:
SELECT s.id, s.code, s.name, s.db_name AS dbName, s.description, s.status, s.created_by AS createdBy, s.created_date AS createdDate, s.updated_by AS updatedBy, s.updated_date AS updatedDate FROM schools s WHERE s.deleted = false
AND (s.code ILIKE '%' || #{keyword} || '%' OR s.name ILIKE '%' || #{keyword} || '%' OR s.description ILIKE '%' || #{keyword} || '%')
ORDER BY s.created_date DESC LIMIT #{limit} OFFSET #{offset}
